#include <stdio.h>
/*
 * ex09：从按下电源到 login 提示符——引导链的 6 个阶段
 * 为什么值得记：线上机器起不来时，屏幕上停在哪一句，直接决定你该查什么。
 */
typedef struct {
    const char *stage;
    const char *what;      /* 这一阶段做什么 */
    const char *failure;   /* 失败时的典型现象 */
} Stage;

int main(void) {
    Stage st[] = {
        {"1. BIOS/UEFI 自检", "上电自检(POST)、枚举设备、按启动顺序选设备",
         "无显示 / 蜂鸣报警 -> 内存或显卡硬件问题"},
        {"2. 读引导扇区", "读第一块设备的 MBR 前 512 字节（末尾 0x55AA 才合法）",
         "\"Missing operating system\" -> 引导记录被破坏或分区表错"},
        {"3. 引导加载程序", "GRUB 读 /boot/grub/grub.cfg，加载内核镜像与 initramfs",
         "grub rescue> -> grub.cfg 路径错或 /boot 被删"},
        {"4. 内核解压与初始化", "建立页表、初始化调度器/中断/驱动子系统",
         "Kernel panic - not syncing -> 驱动或根文件系统问题"},
        {"5. 挂载根文件系统", "按 root= 参数挂载 /，必要时从 initramfs 里切换根",
         "\"VFS: Unable to mount root fs\" -> root= 写错或缺磁盘驱动"},
        {"6. init/systemd", "启动用户态服务，进入多用户目标，最后给出登录提示",
         "emergency mode / 卡在 starting -> 单元文件或磁盘挂载失败"}
    };
    int n = (int)(sizeof(st) / sizeof(st[0]));

    printf("%-22s %s\n", "阶段", "做什么");
    printf("========================================================================\n");
    for (int i = 0; i < n; i++) {
        printf("%-22s %s\n", st[i].stage, st[i].what);
    }
    printf("\n%s\n", "各阶段失败时的典型现象（排障用）：");
    for (int i = 0; i < n; i++) {
        printf("  %-20s %s\n", st[i].stage, st[i].failure);
    }
    printf("\n结论：引导是「一环交一环」的接力，任何一环断了，后面全都不会发生。\n");
    return 0;
}
